import {plannerDays} from './classroom-planner-ui.mjs';
export function createFamilyUI({esc:e}){let stamp=0;const urls=[];const files=list=>(list||[]).map(f=>{const url=URL.createObjectURL(new Blob([Uint8Array.from(atob(f.data),c=>c.charCodeAt(0))],{type:'application/octet-stream'}));urls.push(url);return '<a class="vle-file" href="'+url+'" download="'+e(f.name)+'">'+e(f.name)+' ↓</a>';}).join('');
 const href=(child,tab='overview',date='',issue='',item='')=>'#/family?'+new URLSearchParams({child,tab,...(date?{date}:{}),...(issue?{issue}:{}),...(item?{item}:{})});
 const day=d=>d?new Date(d.slice(0,10)+'T12:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'No deadline';
 async function api(path){const r=await fetch('/api/family/'+path,{credentials:'same-origin',cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||'Could not open the family portal.');return d;}
 function page(params){for(const url of urls.splice(0))URL.revokeObjectURL(url);const token=++stamp;queueMicrotask(()=>mount(params,token));return '<section class="vle family-portal"><div class="vle-heading"><h1>Family portal</h1><span class="vle-badge">2026–2027</span></div><div id="family-content" aria-live="polite">Opening your family’s school day…</div></section>';}
 async function mount(params,token){try{const s=await api('summary');if(token!==stamp)return;const c=s.children.find(c=>c.id===params.get('child'))||s.children[0];if(!c){document.querySelector('#family-content').innerHTML='<p class="vle-note">No active children are linked to this account. Please contact the school office.</p>';return;}if(params.get('child')&&!s.children.some(c=>c.id===params.get('child')))throw Error('This child is not linked to your family account.');const d=await api('child?'+new URLSearchParams({id:c.id,...(params.get('date')?{date:params.get('date')}:{})})),tab=params.get('tab')||'overview';let body='';
  const openWork=d.work.filter(t=>!['Returned','Turned in'].includes(t.status));const work=()=>'<div class="family-work">'+openWork.map((t,index)=>(index===6?'<details class="vle-panel"><summary>Show '+(openWork.length-6)+' more tasks</summary>':'')+'<details class="family-task"><summary><span><strong>'+e(t.title)+'</strong><small>'+e(t.subject)+' · '+e(t.className)+'</small></span><span><small>'+day(t.due)+(t.minutes?' · '+t.minutes+' min':'')+'</small><b class="'+(t.status==='Overdue'?'family-overdue':'')+'">'+e(t.status)+'</b></span></summary><p class="vle-prose">'+e(t.description||'Ask your child to open this task in Classroom for the instructions.')+'</p></details>'+((index===openWork.length-1&&openWork.length>6)?'</details>':'')).join('')+'</div>';
  const feedback=()=>d.feedback.map(f=>'<article class="vle-panel"><div class="learning-section-title"><h3>'+e(f.title)+'</h3><strong>'+(f.maximum>0?f.mark+'/'+f.maximum+' · '+Math.round(f.mark/f.maximum*100)+'%':'Unscored')+'</strong></div><small>'+e(f.subject)+' · Returned '+day(f.returnedAt)+'</small><p class="vle-prose">'+e(f.feedback||'Your child’s teacher returned this work.')+'</p>'+(f.rubric.length?'<details><summary>Marking rubric</summary>'+f.rubric.map(r=>'<p><strong>'+e(r.title)+'</strong> · '+e(r.level)+' · '+r.points+' points</p>').join('')+'</details>':'')+'</article>').join('')||'<p class="learning-empty">No returned feedback yet. Draft marks and unreturned work are private.</p>';
  if(tab==='overview')body='<div class="learning-stats"><div><strong>'+d.summary.todo+'</strong><span>To do</span></div><div><strong>'+d.summary.overdue+'</strong><span>Overdue</span></div><div><strong>'+d.feedback.length+'</strong><span>Returned results</span></div></div><div class="learning-dashboard"><section class="vle-panel"><h3>Coming up</h3>'+d.work.filter(t=>!['Returned','Turned in'].includes(t.status)).slice(0,5).map(t=>'<div class="family-upcoming"><strong>'+e(t.title)+'</strong><small>'+e(t.subject)+' · '+day(t.due)+'</small></div>').join('')+'<p><a href="'+href(c.id,'work',d.date)+'">View all work →</a></p></section><section class="vle-panel"><h3>School attendance</h3><p>'+day(d.date)+'</p><strong>'+e(d.attendance.schoolStatus)+'</strong><p><a href="'+href(c.id,'attendance',d.date)+'">View recorded lessons →</a></p></section></div><section class="vle-panel"><h3>Class announcements</h3>'+d.announcements.slice(0,5).map(p=>'<details><summary>'+e(p.title)+' · '+e(p.className)+'</summary><p class="vle-prose">'+e(p.body)+'</p><small>'+e(p.author)+' · '+day(p.createdAt)+'</small></details>').join('')+(d.announcements.length?'':'<p>No class announcements yet.</p>')+'</section>';
  if(tab==='work')body='<h2>Work & deadlines</h2><p>Upcoming and missing work across your child’s subjects. Hand-in and changes happen through the student account.</p>'+work()+'<details class="vle-panel"><summary>Turned-in & returned work</summary>'+d.work.filter(t=>['Returned','Turned in'].includes(t.status)).map(t=>'<p>'+e(t.title)+' · '+e(t.subject)+' · '+e(t.status)+'</p>').join('')+'</details>';
  if(tab==='feedback')body='<h2>Released feedback & grades</h2><p>Only work returned by a teacher is shown here.</p>'+feedback();
  if(tab==='attendance')body='<h2>Recorded attendance</h2><p>Registration: <strong>'+e(d.attendance.schoolStatus)+'</strong>. Lessons without a saved register are not counted as absences.</p><section class="vle-panel table-wrap"><table class="data-table"><thead><tr><th>Period</th><th>Class</th><th>Status</th><th>Arrival</th></tr></thead><tbody>'+d.attendance.lessons.map(l=>'<tr><td>'+e(l.period)+'</td><td>'+e(l.className)+'</td><td>'+e(l.status)+'</td><td>'+e(l.arrival||'—')+'</td></tr>').join('')+'</tbody></table>'+(d.attendance.lessons.length?'':'<p class="learning-empty">No attendance has been recorded for this date.</p>')+'</section><details class="vle-panel"><summary>Scheduled lessons</summary>'+d.lessons.map(l=>'<p>'+e(l.from)+'–'+e(l.to)+' · '+e(l.className)+'</p>').join('')+'</details>';
  if(tab==='reports'){if(params.get('issue')){const r=await api('report?'+new URLSearchParams({childId:c.id,issueId:params.get('issue')}));body='<p><a href="'+href(c.id,'reports',d.date)+'">← Issued reports</a> <button type="button" class="btn" id="family-print">Print / Save as PDF</button></p>'+reportHTML(r);}else body='<h2>Issued school reports</h2><p>Reports appear after the school formally issues them. Approval alone does not publish a report.</p>'+d.reports.map(r=>'<a class="family-report-link vle-panel" href="'+href(c.id,'reports',d.date,r.id)+'"><strong>'+e(r.title)+'</strong><span>Version '+r.version+' · Issued '+day(r.issuedAt)+' →</span></a>').join('')+(d.reports.length?'':'<p class="learning-empty">No reports have been issued yet.</p>');}
  if(tab==='week'){const w=await api('planner?'+new URLSearchParams({childId:c.id,date:d.date})),shift=n=>new Date(Date.parse(w.start+'T12:00Z')+n*86400000).toISOString().slice(0,10);body='<div class="learning-section-title"><h2>Weekly learning plan</h2><div class="vle-actions"><a href="'+href(c.id,'week',shift(-7))+'">← Previous week</a><a href="'+href(c.id,'week',shift(7))+'">Next week →</a></div></div><p>'+w.summary.deadlines+' deadlines · '+w.summary.events+' published events · '+w.summary.minutes+' estimated minutes remaining'+(w.summary.unestimated?' · '+w.summary.unestimated+' tasks have no time estimate':'')+'. School time: Tashkent.</p>'+plannerDays(w,{e,taskLink:t=>e(t.title),eventLink:()=>'',showCompleted:true});}
  if(tab==='portfolio'){const item=params.get('item'),r=await api('portfolio?'+new URLSearchParams({childId:c.id,...(item?{itemId:item}:{})}));if(item)body='<p><a href="'+href(c.id,'portfolio',d.date)+'">← Shared portfolio</a></p><article class="vle-panel"><h2>'+e(r.title)+'</h2><p class="vle-prose">'+e(r.reflection)+'</p><small>'+e((r.tags||[]).join(' · '))+'</small>'+files(r.files)+(r.source?'<details><summary>Returned work · '+e(r.source.title)+' · '+r.source.mark+'/'+r.source.maximum+'</summary><p class="vle-prose">'+e(r.source.answer||'')+'</p><p>'+e(r.source.feedback||'')+'</p>'+files(r.source.files)+'</details>':'')+'<p class="vle-feedback">'+e(r.teacherNote||'Approved by the teacher.')+'</p></article>';else body='<h2>Shared portfolio</h2><p>Work selected by your child and explicitly approved by a teacher for family sharing.</p><div class="community-grid">'+r.map(p=>'<a class="community-card vle-panel" href="'+href(c.id,'portfolio',d.date,'',p.id)+'"><h3>'+e(p.title)+'</h3><small>'+e(p.tags.join(' · '))+' · '+day(p.reviewedAt)+'</small></a>').join('')+'</div>'+(r.length?'':'<p class="learning-empty">No entries have been shared yet.</p>');}
  const tabs=[['overview','Overview'],['week','Week'],['work','Work'],['feedback','Feedback & grades'],['attendance','Attendance'],['portfolio','Portfolio'],['reports','Reports']];if(token!==stamp)return;document.querySelector('#family-content').innerHTML='<p class="vle-note">Read-only access for your linked children. Test records stay in this browser.</p><div class="family-child-heading"><label>Child <select id="family-child">'+s.children.map(ch=>'<option value="'+e(ch.id)+'" '+(ch.id===c.id?'selected':'')+'>'+e(ch.name)+' · '+e(ch.groupName)+'</option>').join('')+'</select></label><label>Day <input type="date" id="family-date" value="'+d.date+'"></label></div><nav class="learning-nav" aria-label="Family pages">'+tabs.map(([v,t])=>'<a '+(v===tab?'aria-current="page"':'')+' href="'+href(c.id,v,d.date)+'">'+t+'</a>').join('')+'</nav>'+body;document.querySelector('#family-child').addEventListener('change',ev=>location.hash=href(ev.target.value,tab,d.date));document.querySelector('#family-date').addEventListener('change',ev=>location.hash=href(c.id,tab,ev.target.value));document.querySelector('#family-print')?.addEventListener('click',()=>window.print());
 }catch(error){if(token===stamp&&document.querySelector('#family-content'))document.querySelector('#family-content').innerHTML='<p class="error">'+e(error.message)+'</p>';}}
 function reportHTML(r){return '<article class="family-issued-report"><header><img src="assets/wist-report-logo.png" alt="Westminster International School Tashkent"><h2>'+e(r.cycle.title)+'</h2><p>'+e(r.student.name)+' · '+e(r.student.groupName)+'</p><small>Issued '+day(r.issuedAt)+' · Version '+r.version+'</small></header>'+r.rows.map(row=>'<section><h3>'+e(row.subject)+'</h3><p><strong>Attainment '+e(row.grade)+' · Effort '+e(row.effort)+'</strong></p><p class="vle-prose">'+e(row.comment)+'</p><small>'+e(row.teacher)+'</small></section>').join('')+'<section><h3>Homeroom</h3><p class="vle-prose">'+e(r.homeroom.comment)+'</p><small>'+e(r.homeroom.teacher)+'</small></section><footer>'+e(r.brand?.name||'Westminster International School in Tashkent')+' · '+e(r.brand?.address||'')+'</footer></article>';}
 return{page};
}
